// Room placement is a spatial illustration, not an airflow simulation.
const roomOptions = [
  {name:'Вдоль комнаты', title:'Поток проходит мимо дивана.', text:'Блок на боковой стене оставляет место отдыха в стороне от основной линии потока. На схеме хорошо видно, как положение мебели меняет решение.', unit:[100,85], turn:0, flow:'M130 97C245 85 332 103 470 120', kind:'comfortable'},
  {name:'Напротив дивана', title:'Прямая линия к месту отдыха.', text:'Поток направлен в сторону дивана. Такое расположение стоит обсудить: можно изменить положение блока, угол жалюзи или расположение мебели.', unit:[305,55], turn:90, flow:'M305 83C320 175 333 245 334 330', kind:'direct'},
  {name:'У рабочего места', title:'Рабочая зона попадает на пути.', text:'Линия потока проходит через стол. Для комнаты, в которой работают каждый день, важен не только класс мощности, но и расположение блока относительно человека.', unit:[465,100], turn:180, flow:'M450 112C370 180 255 230 170 285', kind:'desk'},
];
let roomChoice=0;
const roomHost=document.querySelector('#comfort-lab');
roomHost.innerHTML=`<div class="lab-heading"><span class="section-index">02 / ПЛАН КОМФОРТА</span><h2>Комната важнее<br>мощности на коробке.</h2><p>Сравните три положения блока в одной комнате. На схеме — направление потока и места, где вы проводите время.</p></div><div class="comfort-layout"><div class="room-board"><div class="room-board-top"><span>КОМНАТА / <b id="room-area">24</b> М²</span><span>СХЕМА РАСПОЛОЖЕНИЯ</span></div><svg viewBox="0 0 580 440" role="img" aria-labelledby="room-diagram-title"><title id="room-diagram-title">Схема комнаты: блок на боковой стене, диван и рабочий стол</title><defs><pattern id="room-grid" width="20" height="20" patternUnits="userSpaceOnUse"><path d="M20 0H0V20" fill="none" stroke="#c4c9c3" stroke-width=".5"/></pattern></defs><rect x="45" y="45" width="480" height="350" fill="url(#room-grid)" stroke="#64736e" stroke-width="4"/><path d="M170 45H375" stroke="#a6bfbe" stroke-width="8"/><path d="M170 45H375" stroke="#fff" stroke-width="3"/><path d="M45 305v55" stroke="#eef1e9" stroke-width="8"/><path d="M45 305h55M100 305A55 55 0 0 1 45 360" fill="none" stroke="#9ca89e"/><rect x="277" y="310" width="125" height="55" rx="6" fill="#c5cdbc" stroke="#73836c"/><path d="M280 323h119M289 323v40M391 323v40" stroke="#73836c"/><rect x="310" y="233" width="60" height="42" rx="20" fill="#e0dfd1" stroke="#a3a595"/><rect x="88" y="246" width="97" height="49" fill="#d8d9cb" stroke="#879287"/><rect x="119" y="259" width="28" height="18" fill="#82928b"/><circle cx="135" cy="314" r="13" fill="#d4d9d0" stroke="#879287"/><text x="339" y="383" text-anchor="middle">ОТДЫХ</text><text x="133" y="347" text-anchor="middle">РАБОТА</text><text x="276" y="31" text-anchor="middle">ОКНО</text><g id="room-streams"><path id="room-stream-glow" fill="none" stroke-width="47" opacity=".11"/><path id="room-stream" fill="none" stroke-width="2" stroke-dasharray="7 8"/></g><g id="room-unit"><rect x="-32" y="-12" width="64" height="23" rx="5" fill="#fafcf6" stroke="#536a61"/><path d="M-23 6h46" stroke="#536a61"/></g></svg><div class="room-board-bottom"><span><i></i> Направление потока</span><span>Не теплотехнический расчёт</span></div></div><div class="room-reading"><div class="room-controls" role="group" aria-label="Положение кондиционера">${roomOptions.map((o,i)=>`<button type="button" data-room="${i}" aria-pressed="${i===0}"><span>0${i+1}</span>${o.name}<span>↗</span></button>`).join('')}</div><div class="room-explanation" aria-live="polite"><span id="room-kicker">РАСПОЛОЖЕНИЕ / 01</span><h3 id="room-title"></h3><p id="room-copy"></p></div><div class="room-recommendation"><span>ПО ВАШИМ ПАРАМЕТРАМ</span><strong id="room-class">ТИХО / 25</strong><p id="room-match"></p><a id="room-model-link" href="#catalog">Посмотреть систему ↗</a></div></div></div>`;
function setRoom(index){roomChoice=index;const option=roomOptions[index];roomHost.dataset.flow=option.kind;document.querySelector('#room-unit').setAttribute('transform',`translate(${option.unit.join(' ')}) rotate(${option.turn})`);for(const id of ['room-stream','room-stream-glow'])document.getElementById(id).setAttribute('d',option.flow);document.querySelector('#room-title').textContent=option.title;document.querySelector('#room-copy').textContent=option.text;document.querySelector('#room-kicker').textContent=`РАСПОЛОЖЕНИЕ / 0${index+1}`;document.querySelector('#room-diagram-title').textContent=`Схема комнаты. ${option.name}. ${option.title}`;roomHost.querySelectorAll('[data-room]').forEach(button=>button.setAttribute('aria-pressed',String(Number(button.dataset.room)===index)));}
roomHost.querySelectorAll('[data-room]').forEach(button=>button.addEventListener('click',()=>setRoom(Number(button.dataset.room))));
let recommendedModel=0;
function syncRoom(){const area=Number(document.querySelector('#area').value);if(!Number.isFinite(area)||area<8||area>100)return;const sunny=document.querySelector('[name=sun]:checked').value==='sunny';const demand=area*(sunny?.12:.1);document.querySelector('#room-area').textContent=area;recommendedModel=demand<=2.5?0:demand<=3.5?1:demand<=5?2:-1;document.querySelector('#room-class').textContent=recommendedModel<0?'ИНДИВИДУАЛЬНЫЙ ПОДБОР':`ТИХО / ${[25,35,50][recommendedModel]}`;document.querySelector('#room-match').textContent=recommendedModel<0?'Ваша комната выходит за диапазон трёх демонстрационных систем. Нужна оценка помещения.':`Ориентир ${document.querySelector('#capacity').textContent} · ${sunny?'солнечная':'обычная'} сторона. Класс уточняется после оценки окна, высоты и источников тепла.`;document.querySelector('#room-model-link').href=recommendedModel<0?'#contact':'#catalog';document.querySelector('#room-model-link').textContent=recommendedModel<0?'Обсудить комнату ↗':'Посмотреть систему ↗';}
for(const input of document.querySelectorAll('#area,#area-range,[name=sun]'))input.addEventListener('input',syncRoom);
document.querySelector('#room-model-link').addEventListener('click',()=>{if(recommendedModel>=0)selectModel(recommendedModel);});
document.querySelector('#area').addEventListener('change',syncRoom);
setRoom(0);syncRoom();

document.querySelectorAll("[name=sun]").forEach(input=>input.addEventListener("change",syncRoom));
